import pdfplumber, pandas as pd
from collections import defaultdict

pdf_path='/root/population.pdf'
rows=[]
header=None
with pdfplumber.open(pdf_path) as pdf:
    for page in pdf.pages:
        tables=page.extract_tables()
        for table in tables:
            if not table or len(table)<1:
                continue
            # clean cells
            def clean_cell(c):
                if c is None:
                    return ''
                return str(c).strip()
            table = [[clean_cell(c) for c in row] for row in table]
            first = table[0]
            if 'SA2_CODE' in first and 'STATE' in first:
                header = first
                data_rows = table[1:]
            else:
                data_rows = table
            if header is None:
                continue
            for r in data_rows:
                if len(r) < 4:
                    continue
                # pad
                while len(r) < len(header):
                    r.append('')
                rows.append(r[:len(header)])

# Build df
if header:
    df = pd.DataFrame(rows, columns=header)
else:
    df = pd.DataFrame(rows)
print('header', header)
print('shape', df.shape)
print(df.head())
print(df.tail())
# check unique columns
print(df.columns)
PY"}

